export type PracticeDifficulty = 'junior' | 'mid' | 'senior';

export interface PracticeMcq {
  id: string;
  topic: string;
  difficulty: PracticeDifficulty;
  prompt: string;
  options: [string, string, string, string];
  correct: number;
  explanation: string;
  test?: string;
  code?: string;
}

export interface PracticeCodeQuestion {
  id: string;
  topic: string;
  difficulty: PracticeDifficulty;
  prompt: string;
  code?: string;
  reference: string;
  explanation: string;
  test: string;
}

const mcq = (
  id: string,
  topic: string,
  difficulty: PracticeDifficulty,
  prompt: string,
  options: [string, string, string, string],
  correct: number,
  explanation: string,
  extra: Pick<PracticeMcq, 'test' | 'code'> = {},
): PracticeMcq => ({ id, topic, difficulty, prompt, options, correct, explanation, ...extra });

export const KOTLIN_DSA_CODE_QUESTIONS: PracticeCodeQuestion[] = [
  {
    id: 'kd-code-01', topic: 'kotlin', difficulty: 'junior', test: 'kotlin-dsa',
    prompt: 'Write the expression that returns the last valid index of `nums`.',
    code: 'val nums = intArrayOf(4, 8, 12)\nval last = ___',
    reference: 'val last = nums.lastIndex',
    explanation: '`lastIndex` is defined as `size - 1`, so here it is `2`. Careful with the empty array: `lastIndex` returns `-1`, so guard before indexing.',
  },
  {
    id: 'kd-code-02', topic: 'kotlin', difficulty: 'junior', test: 'kotlin-dsa',
    prompt: 'Write a one-line function that returns whether `n` is even.',
    code: 'fun isEven(n: Int): Boolean = ___',
    reference: 'fun isEven(n: Int): Boolean = n % 2 == 0',
    explanation: 'Even means division by two leaves no remainder, and the comparison already yields the Boolean. Prefer `n % 2 == 0` over `n % 2 != 1`, which mishandles negative numbers because `-3 % 2` is `-1` on the JVM.',
  },
  {
    id: 'kd-code-03', topic: 'kotlin', difficulty: 'mid', test: 'kotlin-dsa',
    prompt: 'Complete the frequency count without a not-null assertion.',
    code: 'val counts = mutableMapOf<Char, Int>()\nfor (ch in word) {\n    counts[ch] = ___\n}',
    reference: 'counts[ch] = counts.getOrDefault(ch, 0) + 1',
    explanation: '`getOrDefault` hands back zero the first time a character shows up, so the same line handles both new and existing keys. This counting map is the setup for anagram checks and first-unique-character questions.',
  },
  {
    id: 'kd-code-04', topic: 'kotlin', difficulty: 'mid', test: 'kotlin-dsa',
    prompt: 'Fill in the loop range so every valid array index is visited safely.',
    code: 'for (i in ___) {\n    println(nums[i])\n}',
    reference: `for (i in nums.indices) {
    println(nums[i])
}`,
    explanation: '`indices` is exactly the valid index range of the array, so there is no off-by-one to get wrong. For an empty array the range is empty and the body never runs, which avoids ArrayIndexOutOfBoundsException.',
  },
  {
    id: 'kd-code-05', topic: 'kotlin', difficulty: 'mid', test: 'kotlin-dsa',
    prompt: 'Complete the queue operations so nodes are processed in first-in, first-out order.',
    code: 'val queue = ArrayDeque<Int>()\nqueue.___(start)\nval node = queue.___()',
    reference: `queue.addLast(start)
val node = queue.removeFirst()`,
    explanation: 'Add at the back, remove from the front: that is FIFO, which is what BFS needs. `removeFirst` throws NoSuchElementException on an empty deque, so loop on `queue.isNotEmpty()` or use `removeFirstOrNull()`.',
  },
];

// Timed DSA rounds: two real coding questions per round, ten minutes each.
// These are the problems that keep showing up in Android screening rounds
// (pair with target sum, frequency counting, in-place array work, Kadane,
// bracket matching, sliding window).
export const DSA_ROUND_QUESTIONS: PracticeCodeQuestion[] = [
  {
    id: 'dsa-code-01', topic: 'dsa', difficulty: 'mid', test: 'dsa-round-1',
    prompt: 'Return the indices of the two numbers in `nums` that add up to `target`. Exactly one valid answer exists. Aim for a single pass.',
    code: 'fun twoSum(nums: IntArray, target: Int): IntArray {\n    // your code\n}',
    reference: `fun twoSum(nums: IntArray, target: Int): IntArray {
    val seen = HashMap<Int, Int>()
    for (i in nums.indices) {
        val need = target - nums[i]
        seen[need]?.let { return intArrayOf(it, i) }
        seen[nums[i]] = i
    }
    return intArrayOf()
}`,
    explanation: 'Walk the array once, and for each element ask whether its complement (`target - value`) was already seen. The map lookup is O(1), so the whole thing is O(n) time and O(n) space, against O(n^2) for the nested-loop version. Checking before inserting also handles duplicates like `[3, 3]` with target `6`.',
  },
  {
    id: 'dsa-code-02', topic: 'dsa', difficulty: 'junior', test: 'dsa-round-1',
    prompt: 'Return the first character in `s` that appears exactly once, or `null` if every character repeats.',
    code: 'fun firstUnique(s: String): Char? {\n    // your code\n}',
    reference: `fun firstUnique(s: String): Char? {
    val counts = LinkedHashMap<Char, Int>()
    for (ch in s) counts[ch] = (counts[ch] ?: 0) + 1
    return counts.entries.firstOrNull { it.value == 1 }?.key
}`,
    explanation: 'Count every character, then take the first entry whose count is one. LinkedHashMap keeps insertion order, so "first" is free; with a plain HashMap you would need a second pass over the string instead. O(n) time either way. If the input is guaranteed lowercase ASCII, an IntArray(26) beats the map.',
  },
  {
    id: 'dsa-code-03', topic: 'dsa', difficulty: 'mid', test: 'dsa-round-2',
    prompt: 'Move every `0` in `nums` to the end, in place, keeping the relative order of the non-zero elements.',
    code: 'fun moveZeroes(nums: IntArray) {\n    // your code\n}',
    reference: `fun moveZeroes(nums: IntArray) {
    var write = 0
    for (value in nums) {
        if (value != 0) nums[write++] = value
    }
    while (write < nums.size) nums[write++] = 0
}`,
    explanation: 'A write pointer tracks where the next non-zero belongs. Copy non-zeros forward in one pass, then fill the tail with zeros: O(n) time, O(1) extra space. The stability requirement (keep non-zero order) is what rules out shortcuts like sorting or swapping from both ends.',
  },
  {
    id: 'dsa-code-04', topic: 'dsa', difficulty: 'mid', test: 'dsa-round-2',
    prompt: 'Return the largest sum of any contiguous subarray of `nums`. The array has at least one element and may be all negative.',
    code: 'fun maxSubArray(nums: IntArray): Int {\n    // your code\n}',
    reference: `fun maxSubArray(nums: IntArray): Int {
    var best = nums[0]
    var current = nums[0]
    for (i in 1 until nums.size) {
        current = maxOf(nums[i], current + nums[i])
        best = maxOf(best, current)
    }
    return best
}`,
    explanation: 'This is Kadane: at each element, either extend the running subarray or start fresh from the element, whichever is larger. Initializing both values from `nums[0]` instead of `0` is the detail interviewers probe, because an all-negative array like `[-3, -1, -2]` must return `-1`, not `0`.',
  },
  {
    id: 'dsa-code-05', topic: 'dsa', difficulty: 'mid', test: 'dsa-round-3',
    prompt: 'Return `true` if every bracket in `s` closes in the correct order. `s` contains only the characters `()[]{}`.',
    code: 'fun isValid(s: String): Boolean {\n    // your code\n}',
    reference: `fun isValid(s: String): Boolean {
    val open = ArrayDeque<Char>()
    val pairs = mapOf(')' to '(', ']' to '[', '}' to '{')
    for (ch in s) {
        if (ch in pairs.values) open.addLast(ch)
        else if (open.removeLastOrNull() != pairs[ch]) return false
    }
    return open.isEmpty()
}`,
    explanation: 'The most recently opened bracket must close first, which is stack behavior. `removeLastOrNull` returning null covers a closer with nothing open, like `")("`. The final `isEmpty` check catches leftover openers like `"(("`, the case most first attempts miss.',
  },
  {
    id: 'dsa-code-06', topic: 'dsa', difficulty: 'senior', test: 'dsa-round-3',
    prompt: 'Return the length of the longest substring of `s` that contains no repeating characters.',
    code: 'fun lengthOfLongestSubstring(s: String): Int {\n    // your code\n}',
    reference: `fun lengthOfLongestSubstring(s: String): Int {
    val lastSeen = HashMap<Char, Int>()
    var start = 0
    var best = 0
    for (i in s.indices) {
        val prev = lastSeen[s[i]]
        if (prev != null && prev >= start) start = prev + 1
        lastSeen[s[i]] = i
        best = maxOf(best, i - start + 1)
    }
    return best
}`,
    explanation: 'Slide a window over the string and remember where each character last appeared. On a repeat, jump the window start past the previous occurrence. The `prev >= start` guard matters: for `"abba"`, when the second `a` arrives, the first `a` is already outside the window and must not drag `start` backwards.',
  },
];

export const PRACTICE_MCQS: PracticeMcq[] = [
  // Android fundamentals
  mcq('af-01', 'android-fundamentals', 'junior', 'Which lifecycle callback tells you the Activity is in the foreground and receiving user input?', ['onCreate', 'onStart', 'onResume', 'onRestart'], 2, '`onStart()` only makes the Activity visible; it can still sit behind a dialog or another translucent window. `onResume()` is where it owns the foreground and gets touch input, and `onPause()` is the exact moment it loses that.'),
  mcq('af-02', 'android-fundamentals', 'junior', 'A list loaded from the network must survive rotation without a second network call. Where should it live?', ['In an Activity property', 'In a ViewModel', 'In the onSaveInstanceState Bundle', 'In a companion object'], 1, 'A ViewModel is retained across configuration changes, so the recreated Activity reconnects to the same instance and data. The saved-state Bundle crosses a binder transaction with a size budget of roughly 1 MB, so a large list there risks TransactionTooLargeException. Statics survive too, but they leak and never get cleaned up.'),
  mcq('af-03', 'android-fundamentals', 'junior', 'You want to open a PDF with whatever app can handle it, without naming a specific app. What do you use?', ['An explicit Intent naming the component', 'An implicit Intent with ACTION_VIEW and the MIME type', 'A PendingIntent', 'A ContentProvider query'], 1, 'An implicit Intent declares what you want done (action plus data type) and the system resolves it against installed apps’ intent filters. Since Android 11, package visibility rules apply: to query handlers you may need a `<queries>` declaration in the manifest.'),
  mcq('af-04', 'android-fundamentals', 'mid', 'Which API should run work that must eventually complete even if the app is killed and the device reboots?', ['A started Service', 'Handler.postDelayed', 'WorkManager', 'lifecycleScope.launch'], 2, 'WorkManager persists each request in its own database and reschedules it after process death and reboot, honoring constraints like network or charging. A Service dies with the process, and Handler or lifecycleScope work simply disappears. For exact-time delivery you would reach for AlarmManager instead.'),
  mcq('af-05', 'android-fundamentals', 'mid', 'Why must BroadcastReceiver.onReceive() return quickly?', ['Receivers cannot start any asynchronous work at all', 'It runs on the main thread and the process may be killed or ANR once its short execution window ends', 'It always runs in a separate process', 'The Context it receives expires after one second'], 1, '`onReceive()` runs on the main thread, and once it returns the system considers the receiver done and may kill the process. Blocking it long enough triggers an ANR. Use `goAsync()` only for a few extra seconds of cleanup, and hand anything real to WorkManager.'),
  mcq('af-06', 'android-fundamentals', 'mid', 'A notification action needs to fire an operation as your app, even while your app is not running. What object carries that capability?', ['An explicit Intent', 'A PendingIntent', 'A Binder token', 'A Messenger'], 1, 'A PendingIntent wraps an Intent together with your app identity, so the system or another app can trigger that one operation later with your permissions. Since Android 12 you must pass FLAG_IMMUTABLE or FLAG_MUTABLE when creating one, or the call throws IllegalArgumentException.'),
  mcq('af-07', 'android-fundamentals', 'mid', 'Which of these needs an Activity context and breaks with the Application context?', ['Building a Room database', 'Enqueuing WorkManager work', 'Showing an AlertDialog', 'Creating an OkHttp client'], 2, 'A dialog attaches to the Activity window and inherits its theme, and the Application context has no window token, so WindowManager throws BadTokenException. The rule cuts both ways: long-lived singletons should take the Application context so they never pin a destroyed Activity in memory.'),
  mcq('af-08', 'android-fundamentals', 'mid', 'By default, what does the system do to a visible Activity when the device rotates?', ['Calls onPause and onResume only', 'Destroys and recreates it', 'Moves it to the back stack', 'Kills the whole app process'], 1, 'Rotation is a configuration change, so the Activity is torn down and rebuilt to load resources for the new configuration. ViewModels and saved instance state carry data across. Opting out with android:configChanges means you handle every resource difference yourself, which is rarely worth it.'),
  mcq('af-09', 'android-fundamentals', 'senior', 'Play Console shows an ANR spike after your latest release. What do you look at first?', ['Raise the ANR timeout in developer options', 'The ANR trace, starting with the main thread stack', 'StrictMode output on your own device', 'Move every repository call to Dispatchers.IO'], 1, 'The trace shows exactly what the main thread was doing when the system gave up: a lock it was waiting on, a synchronous binder call, or disk I/O. Fixing threading before reading the evidence often hides the real cause. The timeout itself is fixed by the platform, about five seconds for input dispatch.'),
  mcq('af-10', 'android-fundamentals', 'senior', 'The system kills your backgrounded app to reclaim memory. Which value can be restored when the user comes back?', ['A property on the ViewModel', 'A value stored in SavedStateHandle', 'A field on the Application class', 'An in-flight coroutine'], 1, 'SavedStateHandle plugs into the saved instance state mechanism, which the system persists across process death. A plain ViewModel property only survives configuration changes, because the ViewModel itself dies with the process. Application fields and running coroutines are gone the moment the process is.'),

  // Architecture and patterns
  mcq('ar-01', 'architecture', 'junior', 'What problem does the repository pattern actually solve?', ['It caches every network response automatically', 'Callers get one stable API and never know whether data came from the network, a database, or a cache', 'It converts JSON into Kotlin data classes', 'It keeps Activities out of the back stack'], 1, 'A repository is a boundary: ViewModels ask for domain data and the repository decides where it comes from. Note that caching is a policy you write inside it, not something the pattern gives you for free.'),
  mcq('ar-02', 'architecture', 'junior', 'In MVVM on Android, what should the ViewModel expose to the screen?', ['Direct references to the Views it updates', 'Observable UI state plus functions that handle UI events', 'Room entities for the layout to render', 'The NavController'], 1, 'State flows down, events flow up: the screen renders whatever state the ViewModel publishes and calls back with user actions. The ViewModel must never hold a View or Activity reference, because it outlives them across rotation and would leak the destroyed screen.'),
  mcq('ar-03', 'architecture', 'junior', 'Why pass dependencies through the constructor instead of creating them inside the class?', ['Objects construct faster', 'Tests can hand in fakes without touching global state, and the class declares exactly what it needs', 'It removes the need for interfaces', 'It makes the class thread-safe'], 1, 'A hidden `Repository()` call inside a class welds it to the real implementation. Constructor injection makes requirements visible at the creation site and lets a test pass a deterministic fake. This works with or without a DI framework; Hilt just automates the wiring.'),
  mcq('ar-04', 'architecture', 'mid', 'In unidirectional data flow, what is the only path by which the UI changes?', ['Any layer may mutate shared state directly', 'The UI sends an event up, the state holder produces new state, and the UI re-renders from it', 'The repository pushes view updates to the screen', 'Each screen keeps and edits its own copy of app state'], 1, 'Every state change funnels through one owner, so you can always answer "who changed this and why" by looking at the event that came in. The moment two places can write the same state, you are back to debugging race conditions between them.'),
  mcq('ar-05', 'architecture', 'mid', 'Your domain layer imports android.content.Context. What is the accepted fix?', ['Annotate the use case with @JvmStatic', 'Define an interface in the domain layer and implement it with the Context in an outer layer', 'Make the use case a suspend function', 'Move the use case into the ViewModel'], 1, 'The domain layer stays pure Kotlin so it runs in plain JVM unit tests and never breaks when the framework changes. Anything that genuinely needs Android, like reading a resource or a system service, sits behind a domain-owned interface that the data or app layer implements.'),
  mcq('ar-06', 'architecture', 'mid', 'You choose between three retry policies at runtime, all behind one interface. Which pattern is that?', ['Observer', 'Strategy', 'Builder', 'Decorator'], 1, 'Strategy means interchangeable algorithms behind a single contract, selected at runtime. Decorator is the near-miss distractor: it wraps an existing implementation to add behavior around it, rather than swapping the algorithm itself.'),
  mcq('ar-07', 'architecture', 'mid', 'Why model screen state as a sealed interface with Loading, Content, and Error instead of three Boolean flags?', ['Sealed types serialize faster than Booleans', 'Only one state can exist at a time, and when expressions are checked for exhaustiveness by the compiler', 'Booleans cannot be observed from Compose', 'Sealed types allocate less memory'], 1, 'Three Booleans allow eight combinations, and most of them are nonsense, like loading and error at once. A sealed hierarchy makes those states unrepresentable, and adding a new state turns every non-exhaustive `when` into a compile error instead of a silent bug.'),
  mcq('ar-08', 'architecture', 'mid', 'Which of these belongs in SavedStateHandle?', ['The id of the currently selected item', 'A decoded full-resolution Bitmap', 'An open Room database transaction', 'The full contents of the repository cache'], 0, 'SavedStateHandle is for the small keys you need to rebuild a screen after process death: ids, query text, scroll anchors. It rides the saved instance state Bundle through a binder transaction, so large objects risk TransactionTooLargeException. Reload heavy data from storage using the saved id.'),
  mcq('ar-09', 'architecture', 'senior', 'When does a separate use-case class between ViewModel and repository actually pay for itself?', ['Whenever a ViewModel calls any repository method', 'When real business policy coordinates several repositories or must be reused by more than one screen', 'When you need to inject a coroutine dispatcher', 'When the repository returns a Flow'], 1, 'A use case earns its file when it owns logic: validation, orchestration across sources, or a rule several screens share. A one-line pass-through like `operator fun invoke() = repo.getUser()` adds a layer of indirection with nothing inside it.'),
  mcq('ar-10', 'architecture', 'senior', 'What is the realistic cost of splitting an app into too many small Gradle modules?', ['Modules cannot share code at all', 'Dependency wiring, api/implementation boundaries, and build configuration overhead start to outweigh the isolation you gained', 'R8 stops optimizing across module boundaries', 'Each module requires its own Application class'], 1, 'Modules pay off when they enforce ownership or let Gradle skip rebuilding unchanged code. Split past that and every feature touches five build files, navigation crosses artificial seams, and configuration time grows, while the boundaries no longer map to anything a team actually owns.'),

  // Code output
  mcq('co-01', 'code-snippet-output', 'junior', 'What does `listOf(1, 2, 3).map { it * 2 }` return?', ['[1, 2, 3]', '[2, 4, 6]', '[2, 3, 4]', 'It does not compile because the list is read-only'], 1, '`map` calls the transform once per element and collects the results into a new list; the original is untouched. Read-only limits mutation through `add` or `remove`, not building transformed copies.'),
  mcq('co-02', 'code-snippet-output', 'junior', 'Given `val name: String? = null`, what does `name ?: "fallback"` evaluate to?', ['null', 'fallback', 'It throws NullPointerException', 'It does not compile'], 1, 'The Elvis operator returns the left side when it is non-null and only then evaluates the right side. The right side can also be `return` or `throw`, which is a tidy way to bail out of a function on missing data.'),
  mcq('co-03', 'code-snippet-output', 'junior', 'What does `runCatching { error("boom") }.isFailure` evaluate to?', ['true', 'false', 'Nothing, the IllegalStateException reaches the caller', 'null'], 0, '`error()` throws IllegalStateException, and `runCatching` catches it into a failed Result, so `isFailure` is true. Worth knowing before you sprinkle it everywhere: it also catches CancellationException, which can quietly break coroutine cancellation if you never rethrow it.'),
  mcq('co-04', 'code-snippet-output', 'mid', 'After `val x = mutableListOf(1); val y = x; y += 2`, what is `x`?', ['[1]', '[2]', '[1, 2]', 'It does not compile because y is a val'], 2, '`x` and `y` point at the same MutableList instance. On a MutableList, `+=` compiles to `plusAssign`, which mutates the shared list in place, so the change shows through both names. `val` freezes the reference, never the object behind it.'),
  mcq('co-05', 'code-snippet-output', 'mid', 'What does `listOf("a", "bb").associateBy { it.length }` return?', ['{a=1, bb=2}', '{1=a, 2=bb}', '{1=[a], 2=[bb]}', 'It does not compile because map keys must be strings'], 1, '`associateBy` uses the selector result as the key and the original element as the value. If two elements produce the same key, the later one silently replaces the earlier one; when you need to keep all of them, that is `groupBy`.'),
  mcq('co-06', 'code-snippet-output', 'mid', 'Given `val s: String? = null`, what happens when `println(s!!.length)` runs?', ['It prints 0', 'It prints null', 'It throws NullPointerException before println executes', 'It does not compile because s is nullable'], 2, '`!!` tells the compiler to trust you, so it compiles fine. At runtime the null check happens when `s!!` is evaluated, throwing NullPointerException before `.length` or `println` ever run. Every `!!` in a codebase is a bet that someone eventually loses.'),
  mcq('co-07', 'code-snippet-output', 'mid', 'What does `sequenceOf(1, 2, 3).filter { it > 1 }.first()` return?', ['1', '2', '3', 'The list [2, 3]'], 1, 'Sequences are lazy: `first()` pulls elements one at a time until the predicate passes. It rejects 1, accepts 2, and stops; 3 is never even examined. The list version would filter everything first and then take the head.'),
  mcq('co-08', 'code-snippet-output', 'mid', 'Given `data class User(val id: Int)`, what does `User(1) == User(1)` return?', ['true', 'false', 'It depends on whether hashCode was called first', 'It does not compile without overriding equals'], 0, 'For a data class, `==` calls the generated `equals`, which compares primary-constructor properties, so equal ids mean equal objects. `===` on the same two instances returns false, because they are distinct objects on the heap.'),
  mcq('co-09', 'code-snippet-output', 'senior', 'Inside a lambda passed to an inline function, what does a bare `return` do?', ['Returns from the lambda only', 'Returns from the function that called the inline function', 'Throws IllegalStateException at runtime', 'It never compiles inside any lambda'], 1, 'Because the lambda body is inlined into the caller, a bare `return` is a non-local return from the enclosing function, exactly like `return` inside a `forEach`. Mark the parameter `crossinline` to forbid it. In a non-inline lambda, only labeled returns like `return@map` compile.'),
  mcq('co-10', 'code-snippet-output', 'senior', 'A Flow producer emits faster than the collector can process. What does adding `conflate()` guarantee?', ['Every emitted value is still delivered eventually', 'The collector always gets the most recent value, and intermediate values may be dropped', 'The producer suspends until the collector catches up', 'Values are buffered without limit'], 1, '`conflate()` lets the producer run ahead and keeps only the latest pending value, dropping the ones in between. That is the right trade for UI state, where only the newest value matters. The default with no operator is the opposite: the producer suspends until the collector is ready.'),

  // Last-minute Kotlin DSA sprint
  mcq('kd-01', 'kotlin', 'junior', 'After mutating the list, what does this code print?', ['[1, 2]', '[1, 2, 3]', '[3]', 'It does not compile because values is a val'], 1, '`values` is a read-only reference to a mutable list, so `add` works fine and the print shows `[1, 2, 3]`. `val` stops you reassigning `values`, not mutating the object it points to.', { test: 'kotlin-dsa', code: 'val values = mutableListOf(1, 2)\nvalues.add(3)\nprintln(values)' }),
  mcq('kd-02', 'kotlin', 'junior', 'Which indices does this exclusive range print?', ['0 1 2 3', '0 1 2', '1 2 3', '1 2'], 1, '`until` excludes the upper bound, so the loop visits 0, 1, and 2 and never touches 3. That is exactly why `0 until size` is the safe idiom for array indices.', { test: 'kotlin-dsa', code: 'for (i in 0 until 3) print("$i ")' }),
  mcq('kd-03', 'kotlin', 'junior', 'Which substring does this half-open range print?', ['otl', 'otli', 'Kot', 'tli'], 0, '`substring(1, 4)` includes index 1 and excludes index 4, so it takes the characters at indices 1, 2, and 3: `otl`. Passing an end index past the length throws StringIndexOutOfBoundsException.', { test: 'kotlin-dsa', code: 'val word = "Kotlin"\nprintln(word.substring(1, 4))' }),
  mcq('kd-04', 'kotlin', 'mid', 'What count does this map lookup print?', ['1', '2', 'null', 'It throws NullPointerException'], 1, 'The key exists, so `getOrDefault` returns the stored 1 and the expression prints 2. The default only kicks in for missing keys, which is what makes this the standard frequency-count idiom.', { test: 'kotlin-dsa', code: 'val counts = mutableMapOf(\'a\' to 1)\nprintln(counts.getOrDefault(\'a\', 0) + 1)' }),
  mcq('kd-05', 'kotlin', 'mid', 'What remains at the top of this stack?', ['10', '20', 'null', 'The deque is empty'], 0, 'Using `addLast` and `removeLast` makes the deque behave as a stack. 20 went on last, so it comes off first, leaving 10 on top. `last()` on an empty deque would throw NoSuchElementException.', { test: 'kotlin-dsa', code: 'val stack = ArrayDeque<Int>()\nstack.addLast(10)\nstack.addLast(20)\nstack.removeLast()\nprintln(stack.last())' }),
  mcq('kd-06', 'kotlin', 'mid', 'In what order are the original and sorted arrays printed?', ['[1, 2, 3] then [1, 2, 3]', '[3, 2, 1] then [3, 2, 1]', '[1, 2, 3] then [3, 1, 2]', '[3, 1, 2] then [1, 2, 3]'], 3, '`sortedArray` returns a sorted copy and leaves the receiver untouched, so `values` still prints `[3, 1, 2]`. The in-place counterpart is `sort()`. Mixing up which functions copy and which mutate is a classic source of interview slips.', { test: 'kotlin-dsa', code: 'val values = intArrayOf(3, 1, 2)\nval sorted = values.sortedArray()\nprintln(values.contentToString())\nprintln(sorted.contentToString())' }),
  mcq('kd-07', 'kotlin', 'mid', 'What does this safe-call and Elvis expression print?', ['fallback', 'null', '0', 'It throws NullPointerException'], 0, 'The safe call `name?.length` short-circuits to null because `name` is null, and the Elvis operator then supplies `fallback`. No NullPointerException is possible on this line; that would need `!!`.', { test: 'kotlin-dsa', code: 'val name: String? = null\nprintln(name?.length ?: "fallback")' }),
  mcq('kd-08', 'kotlin', 'mid', 'What sum is produced by visiting the even indices?', ['4', '5', '6', 'The loop reads past the array'], 1, '`indices` yields 0, 1, 2. The filter keeps indices 0 and 2, whose values are 1 and 4, so the sum is 5. Note the question is about even indices, not even values; misreading that is the trap.', { test: 'kotlin-dsa', code: 'val nums = intArrayOf(1, 2, 4)\nvar sum = 0\nfor (i in nums.indices) {\n    if (i % 2 == 0) sum += nums[i]\n}\nprintln(sum)' }),

  // Coroutines and Flow
  mcq('cf-01', 'coroutines', 'junior', 'What does marking a function `suspend` actually guarantee?', ['It always runs on a background thread', 'It can pause and resume without blocking its thread; which thread runs it is decided by the dispatcher', 'It launches a new coroutine on every call', 'It converts exceptions into Result values'], 1, 'The compiler turns a suspend function into a state machine that can park and resume around suspension points. It says nothing about threads: a suspend function called on Dispatchers.Main runs on the main thread until something like `withContext` or `delay` suspends it.'),
  mcq('cf-02', 'coroutines', 'junior', 'What is the difference between `launch` and `async`?', ['Both return a Job and behave identically', 'launch is fire-and-forget and returns a Job; async returns a Deferred whose result you get with await()', 'async blocks the calling thread until done', 'launch cannot be cancelled'], 1, 'Use `launch` when you need the side effect and `async` when you need the value back. The classic trap: an `async` failure is deferred until `await()`, so a Deferred nobody awaits can hide its exception until the parent scope fails.'),
  mcq('cf-03', 'coroutines', 'junior', 'Why is GlobalScope discouraged for normal app work?', ['It forces everything onto the main thread', 'Its coroutines are tied to the process, so nothing cancels them when the screen or ViewModel that started them dies', 'It cannot call suspend functions', 'It runs on a single shared thread'], 1, 'Work launched in GlobalScope keeps running, and keeps referencing whatever it captured, long after the screen that wanted it is gone. viewModelScope and lifecycleScope exist precisely so cancellation follows ownership. GlobalScope is for process-lifetime work, which is rare.'),
  mcq('cf-04', 'coroutines', 'mid', 'One child coroutine inside `coroutineScope { }` throws IOException. What happens to its siblings?', ['They continue running to completion', 'They are cancelled, and the scope rethrows the IOException to its caller', 'They finish first, then the exception is thrown', 'The exception is dropped unless a handler is installed'], 1, 'That is structured concurrency: a failing child cancels the parent, which cancels every sibling, and the exception propagates out of the scope. When siblings must survive each other, use `supervisorScope`, and give each child its own error handling.'),
  mcq('cf-05', 'coroutines', 'mid', 'A search field emits a new query on every keystroke, and each query starts a network Flow. Which operator cancels the stale request when a new query arrives?', ['combine', 'flatMapLatest', 'zip', 'onEach'], 1, '`flatMapLatest` cancels the previous inner Flow the moment upstream emits again, so a slow response for "andr" can never overwrite results for "android". In real search UIs it is usually paired with `debounce` and `distinctUntilChanged`.'),
  mcq('cf-06', 'coroutines', 'mid', 'Which type always holds a current value and hands it to every new collector immediately?', ['SharedFlow', 'StateFlow', 'Channel', 'A cold Flow built with flow { }'], 1, 'StateFlow always has `.value`, replays it to new collectors, and skips emissions equal to the current value. SharedFlow can be configured with replay but has no required current value, which is why one-off events fit SharedFlow and screen state fits StateFlow.'),
  mcq('cf-07', 'coroutines', 'mid', 'What does `flowOn(Dispatchers.IO)` actually move?', ['The collector and everything below it', 'The operators and producer upstream of the flowOn call', 'Every coroutine in the application', 'Only catch and retry operators'], 1, '`flowOn` changes the context for the segment above it and leaves the collector in its own context. That boundary is the whole point: the flow can read disk on IO while the collector safely touches UI state on Main without any explicit thread hop.'),
  mcq('cf-08', 'coroutines', 'mid', 'Inside a coroutine on Dispatchers.Main, what is the difference between `delay(1000)` and `Thread.sleep(1000)`?', ['There is no observable difference', 'delay suspends the coroutine and frees the main thread; sleep blocks the main thread and freezes the UI', 'sleep suspends the coroutine; delay blocks the thread', 'delay only works on background dispatchers'], 1, '`delay` schedules a resumption and releases the thread, so the UI keeps drawing. `Thread.sleep` holds the main thread hostage for the full second: frames drop, input queues up, and past a few seconds the system raises an ANR.'),
  mcq('cf-09', 'coroutines', 'senior', 'You are wrapping a callback-based API that returns one result and supports cancellation. What is the right bridge to coroutines?', ['runBlocking around the callback', 'suspendCancellableCoroutine, resuming exactly once and unregistering in invokeOnCancellation', 'GlobalScope.async with a CompletableDeferred', 'A while loop polling a volatile field'], 1, 'For a single-shot callback, `suspendCancellableCoroutine` turns registration into a suspension point; the contract is resume exactly once and clean up the callback in `invokeOnCancellation`. When the API delivers a stream of callbacks instead, the equivalent tool is `callbackFlow`.'),
  mcq('cf-10', 'coroutines', 'senior', 'What does building a scope with SupervisorJob change about failures?', ['Children can no longer be cancelled by the parent', 'A failed child no longer cancels its sibling coroutines', 'Unhandled exceptions are retried automatically', 'All children move to Dispatchers.IO'], 1, 'SupervisorJob cuts the child-to-parent failure propagation while keeping parent-to-child cancellation, which is why viewModelScope uses one: a crashed refresh must not kill an unrelated collector. Each child still needs its own handling, or the exception hits the CoroutineExceptionHandler.'),

  // Jetpack Compose
  mcq('jc-01', 'jetpack-compose', 'junior', 'How long does a value stored with `remember { }` survive?', ['Until the process is killed', 'As long as its call site stays in the composition; it is lost when the Activity is recreated', 'For the lifetime of the ViewModel', 'Until the user leaves the app'], 1, '`remember` caches a value in the composition, keyed by call position, so it survives recomposition. Leave the composition or rotate the device and it is gone. When the value should survive recreation, that is `rememberSaveable`; when it should survive navigation, it belongs in a ViewModel.'),
  mcq('jc-02', 'jetpack-compose', 'junior', 'What causes a composable scope to be scheduled for recomposition?', ['Any function call inside it', 'A change to a snapshot State value that the scope read during composition', 'Every new frame from the display', 'Only a configuration change'], 1, 'Compose records which State objects each scope reads while composing. When one of those values changes, only the scopes that read it are invalidated. State nobody reads can change all day without a single recomposition, which is the key to writing cheap UI.'),
  mcq('jc-03', 'jetpack-compose', 'junior', 'What does `rememberSaveable` add over plain `remember`?', ['Nothing, they are aliases', 'The value also survives Activity recreation and process death via saved instance state', 'The value is written to DataStore', 'The value becomes observable'], 1, '`rememberSaveable` routes the value through the saved instance state Bundle, so rotation and process death restore it. Anything that is not Bundle-friendly needs a custom Saver. Keep it small: this path has the same binder size limits as onSaveInstanceState.'),
  mcq('jc-04', 'jetpack-compose', 'mid', 'Why should items in a LazyColumn whose data reorders have stable keys?', ['Keys enable paging from the network', 'Compose uses keys to move remembered state and animations with the item instead of leaving them at the old position', 'Keys keep every item composed permanently', 'The compiler requires them'], 1, 'Without keys, item state is positional: delete row 3 and row 4 inherits its state, like a stale swipe or checkbox. With stable ids, identity follows the data. Duplicate keys crash with IllegalArgumentException, so derive them from something genuinely unique.'),
  mcq('jc-05', 'jetpack-compose', 'mid', 'When is the coroutine inside `LaunchedEffect(userId)` cancelled and relaunched?', ['On every recomposition', 'When userId changes, or when the effect leaves the composition entirely', 'Only when the process restarts', 'Whenever any state in the same file changes'], 1, 'The effect keeps running across recompositions while the key stays equal. A new `userId` cancels the running coroutine and starts a fresh one, and leaving composition cancels it for good. Passing `Unit` as the key means "run once per composition lifetime".'),
  mcq('jc-06', 'jetpack-compose', 'mid', 'A "scroll to top" button should appear once the first visible index of a LazyColumn passes 10. Which API avoids recomposing on every scrolled pixel?', ['rememberUpdatedState', 'derivedStateOf { listState.firstVisibleItemIndex > 10 }', 'rememberSaveable', 'DisposableEffect'], 1, 'Reading `firstVisibleItemIndex` directly in composition recomposes on every scroll frame. Wrapping the comparison in `derivedStateOf` means readers are only invalidated when the Boolean actually flips from false to true or back, which is a handful of times instead of hundreds.'),
  mcq('jc-07', 'jetpack-compose', 'mid', 'What does "state hoisting" mean in Compose?', ['Persisting state to disk before recomposition', 'Moving state up to the caller, which passes the value down and receives changes through a callback', 'Replacing remember with a global singleton', 'Upgrading remember to rememberSaveable'], 1, 'The hoisted composable takes `value` and `onValueChange` and owns nothing, exactly like TextField. That keeps a single source of truth in the caller and makes the composable reusable, previewable, and trivial to test, because its entire behavior is inputs in, events out.'),
  mcq('jc-08', 'jetpack-compose', 'mid', 'Where should expensive work like sorting a large list not happen?', ['In the ViewModel when state is produced', 'Directly in a composable body that recomposes often', 'In the repository layer', 'Behind remember with the list as its key'], 1, 'A composable body can rerun at high frequency, and re-sorting on each pass burns frame budget. Produce derived data in the ViewModel, or at minimum cache it with `remember(list)` so it recomputes only when the input actually changes.'),
  mcq('jc-09', 'jetpack-compose', 'senior', 'A value animates every frame. Where should you read it so the smallest part of the pipeline reruns?', ['In composition, at the top of the composable', 'In the draw phase, inside a drawBehind or graphicsLayer lambda', 'In the ViewModel', 'In a LaunchedEffect'], 1, 'Compose invalidates the phase where a state read happens. Read the animated value only inside a draw lambda and each frame redraws pixels without recomposing or re-measuring anything. Reading it in composition instead drags the whole scope through every frame of the animation.'),
  mcq('jc-10', 'jetpack-compose', 'senior', 'A long-running LaunchedEffect must call the latest `onTimeout` lambda without being restarted when that lambda changes. What do you use?', ['Add onTimeout to the LaunchedEffect keys', 'val current by rememberUpdatedState(onTimeout) inside the effect', 'Switch to DisposableEffect', 'Recreate the effect on every recomposition'], 1, '`rememberUpdatedState` gives the running effect a stable holder whose value recomposition keeps fresh, so the timer survives and still calls the newest callback when it fires. Putting the lambda in the keys would restart the countdown every time the caller recomposes.'),

  // Kotlin
  mcq('kt-01', 'kotlin', 'junior', 'What does the type `String?` mean in Kotlin?', ['A mutable String', 'A String that may be null, and the compiler forces you to handle that before member access', 'A Java platform type with unknown nullability', 'A String initialized lazily'], 1, 'Nullability is part of the type system: you cannot call `.length` on a `String?` until you have dealt with the null case via `?.`, `?:`, a check, or `!!`. Platform types are the separate case: values from Java arrive with unknown nullability written as `String!`.'),
  mcq('kt-02', 'kotlin', 'junior', 'What is the difference between `==` and `===` in Kotlin?', ['They are interchangeable', '== calls equals() for structural equality; === checks that both references point to the same instance', '== compares references; === compares values', '=== works only on primitive types'], 1, '`==` is null-safe structural equality that compiles to `equals()`, so two data class instances with equal properties are `==`. `===` is identity. Fun edge: small boxed Ints are cached by the JVM, so `===` on boxed 100 can be true while boxed 1000 is false.'),
  mcq('kt-03', 'kotlin', 'junior', 'Which members does a data class generate from its primary constructor properties?', ['Only the constructor itself', 'equals, hashCode, toString, copy, and componentN functions', 'A Parcelable implementation', 'A builder and a serializer'], 1, 'The generated members come from primary-constructor properties only. A property declared in the class body is excluded from equality, hashing, copy, and destructuring, which surprises people when two "equal" objects differ in a body property.'),
  mcq('kt-04', 'kotlin', 'mid', 'When is `lateinit` the right choice for a property?', ['For a nullable Int with a default', 'For a non-null var that cannot be initialized at construction time, like a field a framework injects later', 'For an expensive val computed on first access', 'For compile-time constants'], 1, 'lateinit defers initialization of a non-null `var` reference type; reading it early throws UninitializedPropertyAccessException, and `::field.isInitialized` lets you check. It does not work on primitives or `val`. The lazy-computed `val` case is `by lazy { }` instead.'),
  mcq('kt-05', 'kotlin', 'mid', 'What does declaring a generic type as `out T` mean?', ['T may only appear as function parameters', 'T only appears in output positions, making the type covariant: a Producer<Dog> can be used as a Producer<Animal>', 'T is always nullable', 'T is available at runtime despite erasure'], 1, '`out` declares the type is a producer of T, never a consumer, and the compiler enforces it. That is what lets `List<Dog>` be passed where `List<Animal>` is expected, while `MutableList` cannot, because adding an Animal to a list of Dogs must stay illegal.'),
  mcq('kt-06', 'kotlin', 'mid', 'What does `sealed` give you that an ordinary open class does not?', ['Subclasses may be declared in any module', 'The compiler knows every direct subtype, so a when expression over it is exhaustive without an else branch', 'Each subtype becomes a singleton', 'Automatic Parcelable support'], 1, 'Direct subtypes of a sealed type must live in the same package and module, so the compiler has the full list. Add a new subtype and every non-exhaustive `when` breaks the build, which is exactly what you want for UI state and navigation results. Unlike enums, each subtype carries its own data.'),
  mcq('kt-07', 'kotlin', 'mid', 'When does converting a long collection chain to `asSequence()` actually help?', ['Always, sequences are strictly faster', 'On large inputs with several chained operations, especially when a terminal like first() can stop early', 'Only on small lists', 'Whenever you need indexed random access'], 1, 'Each list operator materializes a full intermediate list, while a sequence pulls one element through the whole chain at a time and can short-circuit. On a five-element list the sequence machinery costs more than it saves, so this is a "measure on real data" answer, not a reflex.'),
  mcq('kt-08', 'kotlin', 'mid', 'How are extension functions dispatched?', ['Dynamically, based on the runtime type of the receiver', 'Statically, based on the compile-time type of the receiver', 'Through reflection at first call', 'Via a generated subclass of the receiver'], 1, 'An extension compiles to a static function with the receiver as its first parameter, so the declared type decides which extension runs, not the runtime type. And when a member and an extension share a signature, the member always wins, silently.'),
  mcq('kt-09', 'kotlin', 'senior', 'What does a `reified` type parameter on an inline function enable?', ['Creating generic arrays of any T', 'Using T at runtime, like `value is T` checks and `T::class`, without passing a Class parameter', 'Making T covariant', 'Disabling type erasure for the whole program'], 1, 'Because the function is inlined, the compiler substitutes the concrete type at each call site, so the type survives where erasure would normally destroy it. This is how `Gson.fromJson<User>(json)` style APIs work. It applies only inside that inline function, not to generics globally.'),
  mcq('kt-10', 'kotlin', 'senior', 'What is the `Nothing` type for?', ['A nullable alias of Unit', 'The return type of expressions that never return normally, such as a function that always throws; it is a subtype of every type', 'A marker for empty collections', 'The default upper bound of type parameters'], 1, '`Nothing` has zero values, and being a subtype of everything lets a `throw` or `TODO()` sit anywhere an expression is expected: `val name = user.name ?: error("missing")` types as String. The default upper bound of type parameters is `Any?`, a different thing entirely.'),

  // Mobile system design
  mcq('sd-01', 'system-design', 'junior', 'In an offline-first app, what does the UI observe as its single source of truth?', ['The most recent network response', 'The local database, which background sync keeps updated', 'Push notification payloads', 'An in-memory cache owned by the Activity'], 1, 'The UI renders from local storage, so the app works identically with or without a connection. Sync writes remote changes into that store rather than racing the UI with a second source of truth. Room plus a Flow-emitting DAO is the standard shape of this on Android.'),
  mcq('sd-02', 'system-design', 'junior', 'A feed gets new posts constantly. Why does cursor pagination hold up where offset pagination breaks?', ['Cursors compress the response body', 'Inserts shift offset boundaries, causing duplicated and skipped items; a cursor resumes from a stable ordering key', 'Cursors cache every page forever', 'Offset pagination cannot be sorted'], 1, 'Page 2 with offset 20 means "rows 20 to 39 right now", and ten new posts shift everything, so users see repeats or holes. A cursor like "items after id 1041" pins the position to data, not to a count, so it survives concurrent writes.'),
  mcq('sd-03', 'system-design', 'junior', 'A payment request times out and the client retries. What stops the card being charged twice?', ['Using TLS for the retry', 'An idempotency key: the server stores the first outcome and returns it for any duplicate attempt', 'A shorter connect timeout', 'Retrying only on unmetered networks'], 1, 'A timeout tells you nothing: the first request may have succeeded just before the response was lost. The client sends the same generated key on the retry, and the server recognizes it and replays the original result instead of executing the charge again.'),
  mcq('sd-04', 'system-design', 'mid', 'Which caching policy shows cached data instantly and refreshes it in the background?', ['Write-through', 'Stale-while-revalidate', 'No-store', 'Cache-only with manual invalidation'], 1, 'Serve what you have, fetch in the background, update when it lands: users see content in one frame instead of a spinner. The design question it forces is how stale is acceptable, and whether the product needs a visible "updated just now" signal for trust.'),
  mcq('sd-05', 'system-design', 'mid', 'Why should exponential backoff include random jitter?', ['It reduces the average wait time', 'Without it, every client that failed together retries together, hammering the recovering server in synchronized waves', 'It removes the need for a retry limit', 'It gives premium users priority'], 1, 'After a shared outage, thousands of devices hit the same backoff schedule and retry in the same second, which can knock the service back over. Randomizing each delay spreads the load. Retries should also be capped and reserved for transient, safe-to-repeat failures.'),
  mcq('sd-06', 'system-design', 'mid', 'Five in-flight requests all fail with 401 because the access token just expired. What should the client do?', ['Each request refreshes the token independently', 'Run one refresh; the other requests wait for it and then retry with the new token', 'Sign the user out immediately', 'Retry all five with the expired token'], 1, 'Parallel refreshes race: with rotating refresh tokens, the second refresh can invalidate the first and log the user out. A single-flight refresh behind a mutex, with waiters retrying once on the new token, is the standard fix, and OkHttp Authenticator is where it usually lives.'),
  mcq('sd-07', 'system-design', 'mid', 'What is the first durability step in a mobile analytics pipeline?', ['Send each event synchronously as it happens', 'Persist events to local storage first, then upload in batches and delete only after the server acknowledges', 'Hold the queue in process memory', 'Drop events while the device is offline'], 1, 'Write the event to disk before anything else, and it survives process death, crashes, and airplane mode. The uploader batches to save radio and battery, retries with backoff, and deletes only on acknowledgement, which is what makes delivery at-least-once instead of best-effort.'),
  mcq('sd-08', 'system-design', 'mid', 'The server responds 429 Too Many Requests with Retry-After: 30. What should the client do?', ['Retry immediately until it succeeds', 'Wait at least the Retry-After value, then retry with bounded backoff', 'Clear the auth session and cache', 'Downgrade the connection to plain HTTP'], 1, 'A 429 is the server telling you exactly how to behave, and honoring Retry-After is the difference between recovering and amplifying the overload. Only idempotent or idempotency-protected requests should be retried automatically at all.'),
  mcq('sd-09', 'system-design', 'senior', 'What is the core trade-off you accept when adding prefetching?', ['Slower compile times for stronger type safety', 'Spending battery, data, and memory now on predictions to cut perceived latency later', 'Weaker encryption for faster handshakes', 'A larger database schema for simpler UI code'], 1, 'Prefetching bets device resources on a guess about the next action. A disciplined design predicts only high-probability actions, respects metered connections and battery saver, caps the budget, and cancels prefetches the moment the prediction is invalidated.'),
  mcq('sd-10', 'system-design', 'senior', 'The OS kills your app halfway through a large sync. What makes the next run safe?', ['Running the sync in an Activity-scoped coroutine', 'Persisted progress markers plus idempotent operations, so replayed steps cannot double-apply', 'A Boolean flag in process memory', 'Posting the remaining work to a Handler'], 1, 'Recovery needs two properties: knowing what was done (durable progress, like a per-page watermark) and being safe to redo the uncertain step (idempotent writes). WorkManager gets the job restarted, but resumability is a property of your sync protocol, not the scheduler.'),

  // Testing and quality
  mcq('tq-01', 'testing-quality', 'junior', 'What should a single unit test verify?', ['As many code paths as fit in one method', 'One observable behavior through the public API', 'The exact sequence of private helper calls', 'That the Android framework behaves correctly'], 1, 'One behavior per test keeps failures diagnostic: the name tells you what broke. Testing through the public API means refactoring internals does not break the suite, and testing the framework itself is wasted effort you cannot fix anyway.'),
  mcq('tq-02', 'testing-quality', 'junior', 'Why prefer an in-memory fake over a mock for a stateful repository?', ['Fakes can never produce errors', 'A fake models real state and behavior, so tests assert outcomes instead of call sequences', 'Mocks require an emulator', 'Fakes are generated by the compiler'], 1, 'A twenty-line fake with a backing map behaves like the real thing: writes then reads work, and error states are a flag away. Mock-heavy tests tend to assert how the result was produced, which welds them to the current implementation.'),
  mcq('tq-03', 'testing-quality', 'junior', 'Which kind of test gives the fastest, most deterministic feedback?', ['An end-to-end test on a physical device', 'A local JVM unit test', 'A manual pass over the release build', 'A full screenshot suite'], 1, 'JVM tests skip the emulator, the framework, and the flake that comes with both, so they run in milliseconds and fail for exactly one reason. They cannot prove integration, which is why the pyramid keeps a thinner layer of instrumented and end-to-end tests above them.'),
  mcq('tq-04', 'testing-quality', 'mid', 'A test fails in roughly one of every twenty CI runs. What is the correct long-term fix?', ['Configure the CI to retry failed tests three times', 'Find and control the source of nondeterminism: time, dispatchers, shared state, or ordering', 'Insert a five-second sleep before the assertion', 'Delete the assertion that fails most'], 1, 'Flakiness is a real bug in the test or the code under test, usually uncontrolled time, threading, or leftover state. Retries just teach the team to ignore red builds. Injecting clocks and dispatchers turns the nondeterminism into something the test controls.'),
  mcq('tq-05', 'testing-quality', 'mid', 'A coroutine under test delays for 30 seconds. How do you test it without waiting 30 seconds?', ['Thread.sleep(31_000) in the test', 'runTest with injected test dispatchers, so virtual time skips the delay instantly', 'Launch it in GlobalScope and poll', 'Shorten the delay in production code for test builds'], 1, '`runTest` runs on virtual time and auto-advances past delays. The catch is that the code must use injected dispatchers: a hardcoded Dispatchers.IO escapes the TestCoroutineScheduler and the test really does wait, or worse, asserts before the work happened.'),
  mcq('tq-06', 'testing-quality', 'mid', 'What does a consumer-driven contract test catch that unit tests on both sides miss?', ['Font rendering regressions', 'The provider changing request or response behavior that consumers depend on, before it reaches production', 'Renamed private methods', 'Gradle configuration drift'], 1, 'Both sides can be green against their own assumptions while the assumptions disagree: a field renamed, a null appearing where one never had. The contract pins the interaction itself, so the provider build fails the moment it breaks a consumer expectation.'),
  mcq('tq-07', 'testing-quality', 'mid', 'Why is asserting every collaborator call and its order usually a design smell in tests?', ['Verification makes tests slower', 'It couples tests to the implementation, so refactors break them while behavior is unchanged', 'It disables code coverage collection', 'Mocking frameworks leak memory'], 1, 'A test that pins the choreography fails when you inline a helper, even though users see identical behavior, and that noise erodes trust in the suite. Save interaction assertions for when the call itself is the contract, like "the charge endpoint is hit exactly once".'),
  mcq('tq-08', 'testing-quality', 'mid', 'What must a Room migration test actually prove?', ['That the migration SQL is formatted consistently', 'That a database created at the old version upgrades to the expected schema with existing data intact', 'That a fresh install creates the database', 'That migrations run off the main thread'], 1, 'The real risk is user data: MigrationTestHelper opens the database at the old version, you insert representative rows, run the real migration, and assert both schema and surviving values. fallbackToDestructiveMigration makes this "pass" by silently wiping the user, which is the failure.'),
  mcq('tq-09', 'testing-quality', 'senior', 'Your module reports 95 percent line coverage. What does that number not tell you?', ['Which lines executed during the run', 'Whether the assertions would actually catch a regression on those lines', 'That the test process ran to completion', 'That the module compiled'], 1, 'Coverage measures execution, not verification: a test that calls everything and asserts nothing scores the same as a rigorous one. Use coverage to find untested areas, and mutation testing if you want evidence the assertions bite.'),
  mcq('tq-10', 'testing-quality', 'senior', 'An intentional redesign turns 40 screenshot tests red. What is the correct workflow?', ['Configure CI to auto-accept new screenshots', 'Review each visual diff like a code review, then deliberately record the new baseline', 'Disable screenshot tests for the affected screens', 'Raise the pixel-difference tolerance until CI passes'], 1, 'The diffs are the review: an unintended padding shift hides easily among 40 expected changes, and blessing it makes the regression the new truth. Auto-accepting or loosening tolerance quietly deletes the protection the suite exists to provide.'),
];
